'use strict';
const assert=require('node:assert/strict'),path=require('node:path'),crypto=require('node:crypto');
const KEY='mcp_workshop',ADMIN_KEY='mcp_server_rce',ID='mcp_audit_gap',PROFILE='mcp-audit-content';
const FOCUSED_PROFILE='mcp-indirect-supply-content',FOCUSED_IDS=Object.freeze(['mcp_indirect_injection','mcp_supply_chain']);
const REMAINING_PROFILE='mcp-remaining-nine-content',REMAINING_IDS=Object.freeze(['mcp_recon','mcp_cmd_injection','mcp_ssrf','mcp_tool_poisoning','mcp_confused_deputy','mcp_broken_authz','mcp_secret_exposure','mcp_audit_gap','mcp_shadow_server']);
function configuration(profile=PROFILE){assert([PROFILE,FOCUSED_PROFILE,REMAINING_PROFILE].includes(profile));return {ids:profile===REMAINING_PROFILE?REMAINING_IDS:FOCUSED_IDS,completed:profile===REMAINING_PROFILE?REMAINING_IDS:['mcp_supply_chain'],browser:profile===REMAINING_PROFILE?1000:400};}
const LIMITS=Object.freeze({browser:400,api:40});
function allowedRequest(url,origin,count,profile=PROFILE){try{const u=new URL(url);return count<=configuration(profile).browser&&(u.origin===origin||['data:','about:','blob:'].includes(u.protocol))&&!/\/(chat|jsonrpc|progress\/reset|progress\/complete|shadow-source\/write)$/.test(u.pathname);}catch{return false;}}
function assertContent(row,expected){for(const k of ['label','hint_content','solution_content'])assert.deepEqual(row[k],expected[k]);}
function learnerMatches({label,hint,solution}){const rows=[...document.querySelectorAll('.obj-name')].filter(e=>e.textContent===label);if(rows.length!==1)return false;const card=rows[0].closest('.obj-content');const buttons=[...card.querySelectorAll('button')].map(e=>e.textContent.trim());return buttons.includes('View Hint')===hint&&buttons.includes('View Solution')===solution;}
function closeAdminDialogs(){
 const preview=[...document.querySelectorAll('button')].filter(e=>e.textContent.trim()==='Close Preview');
 if(preview.length>1)throw Error('Ambiguous preview close control');if(preview.length)preview[0].click();
 const headings=[...document.querySelectorAll('h3')].filter(e=>e.textContent.trim().startsWith('Objectives —'));
 if(headings.length>1)throw Error('Ambiguous objectives dialog');
 if(headings.length){const buttons=[...headings[0].parentElement.querySelectorAll('button')];if(buttons.length!==1)throw Error('Missing unique objectives close control');buttons[0].click();}
}
function adminDialogsClosed(){return ![...document.querySelectorAll('button')].some(e=>e.textContent.trim()==='Close Preview')&&![...document.querySelectorAll('h3')].some(e=>e.textContent.trim().startsWith('Objectives —'));}
async function prepareAdminPage(page,origin){
 if(page.url()!==origin+'/admin/exercises')await page.goto(origin+'/admin/exercises',{waitUntil:'domcontentloaded'});
 await page.waitForSelector('[data-exercise-key="'+ADMIN_KEY+'"]');
 await page.evaluate(closeAdminDialogs);await page.waitForFunction(adminDialogsClosed);
}
async function viewLearner(page,origin,expected,{reload=false}={}){const url=origin+'/vulnerabilities/mcp-server';if(reload||page.url()!==url)await page.goto(url,{waitUntil:'domcontentloaded'});await page.waitForFunction(learnerMatches,{},expected);}
function masterReady(selector){const nodes=document.querySelectorAll(selector);return nodes.length===1&&nodes[0].getAttribute('aria-disabled')==='false';}
async function waitMasterReady(page,selector){try{await page.waitForFunction(masterReady,{timeout:15000},selector);}catch(error){throw Object.assign(Error('MCP master mutation remains pending or stale'),{code:'MCP_MASTER_MUTATION_STALE',cause:error});}}
async function editContentTitle(page,kind,title,onStep=()=>{}){
 assert(['hint','solution'].includes(kind));const dialog=kind==='hint'?'[role="dialog"][aria-labelledby="prompt-injection-hint-editor-title"]':'[role="dialog"][aria-label="Edit MCP solution — mcp_audit_gap"]';
 await page.click('[data-objective-id="'+ID+'"] button[title="Edit '+(kind==='hint'?'Hint':'Solution')+'"]');await page.waitForSelector(dialog);
 const input=kind==='hint'?dialog+' #prompt-injection-hint-title':dialog+' input';await page.$eval(input,e=>{e.focus();e.select();});await page.keyboard.press('Backspace');onStep('typed-'+kind+'-input-cleared');if(await page.$eval(input,e=>e.value)!=='')throw Object.assign(Error('Title input was not cleared'),{code:'MCP_EDITOR_CLEAR_MISMATCH'});await page.type(input,title);onStep('typed-'+kind+'-input-readback');if(await page.$eval(input,e=>e.value)!==title)throw Object.assign(Error('Typed title DOM value mismatch'),{code:'MCP_EDITOR_INPUT_MISMATCH'});onStep('typed-'+kind+'-save');
 const endpoint='/api/admin/exercises/'+KEY+'/objectives/'+ID+'/'+kind,waiting=page.waitForResponse(r=>new URL(r.url()).pathname===endpoint&&r.request().method()==='PUT',{timeout:15000});waiting.catch(()=>{});
 await page.$eval(dialog,e=>{const buttons=[...e.querySelectorAll('button')].filter(b=>b.textContent==='Save Changes'&&!b.disabled);if(buttons.length!==1)throw Error('Missing unique editor save');buttons[0].click();});
 const response=await waiting;assert.equal(response.status(),200);assert.equal(JSON.parse(response.request().postData()).title,title);await page.waitForSelector(dialog,{hidden:true});
}
async function prepareFocusedAdmin(page,remaining,bounded){if(remaining){assert.equal(page.isClosed(),false,'Instructor page must remain open');await page.goto('about:blank');assert.equal(page.isClosed(),false,'Instructor page must remain open');}else await retireUnusedPage(page,bounded);}
async function retireUnusedPage(page,bounded){await bounded(page.close(),10000,'MCP unused page retirement');assert.equal(page.isClosed(),true,'Unused MCP page must be closed');}
function safeFailure(error){return {name:['AssertionError','Error','TimeoutError','TypeError'].includes(error.name)?error.name:'Error',code:typeof error.code==='string'&&/^[A-Z0-9_]{1,64}$/.test(error.code)?error.code:null,operator:['strictEqual','deepStrictEqual','==','!=','===','!==','match','doesNotMatch','fail'].includes(error.operator)?error.operator:null,frames:String(error.stack).split('\n').map(x=>x.match(/((?:tests|server)\/[^ ()]+:\d+:\d+)/)?.[1]).filter(Boolean).slice(0,5)};}
function focusedModalMatches({kind,value}){
 const norm=x=>String(x||'').replace(/\s+/g,' ').trim();let container;
 if(kind==='Preview'){const close=[...document.querySelectorAll('button')].filter(e=>e.textContent.trim()==='Close Preview');if(close.length!==1)return false;container=close[0].parentElement;while(container&&!container.querySelector('h2,h3'))container=container.parentElement;}
 else{const headings=[...document.querySelectorAll('h3')].filter(e=>norm(e.textContent)===kind+': '+value.title);if(headings.length!==1)return false;container=headings[0].parentElement.parentElement;}
 if(!container)return false;const text=norm(container.textContent),parts=[value.title,...(value.hints||[])];if(kind!=='Hint'){parts.push(value.difficulty,value.approach,...(value.tips||[]));for(const e of value.examples||[])parts.push(...(typeof e==='string'?[e]:[e.prompt,e.explanation]));}return parts.filter(x=>typeof x==='string'&&x.length).every(x=>text.includes(norm(x)));
}
function supplyDoneMatches(label){const rows=[...document.querySelectorAll('.obj-name')].filter(e=>e.textContent===label);return rows.length===1&&rows[0].closest('.obj-content')?.parentElement.querySelector('.status-badge')?.textContent==='DONE';}
const CONTROLLED_TIME_SECONDS=165;
function assertTimeProjection(row){assert(row);assert.equal(row.timeSpentSeconds,CONTROLLED_TIME_SECONDS);return row;}
function assertTimeRestoration(before,after,siblingId){assert(before.some(x=>String(x.user_id)===String(siblingId)&&x.duration_seconds===23));assert.deepEqual(after,before);return true;}
